if ($feature.EBikes == null) {
  return `E-Bikes are ALLOWED on paved bike facilities`;
} else if ($feature.EBikes == 'Allowed') {
  return `E-Bikes are ALLOWED on this trail.`;
}
else if ($feature.EBikes == 'Not Allowed') {
  return `E-Bikes are NOT ALLOWED on this trail.`;
} else {
  return ``;
}

var commonName = $feature.CommonName;

if (IsEmpty(commonName)) {
    return "unnamed";
} else if (
    Find("trail", Lower(commonName)) > -1 ||
    Find("crossing", Lower(commonName)) > -1
) {
    return `commonly referred to as ${commonName}`;
} else {
    return `located on ${commonName}`;
}

function MetersToLatLon(x, y) {
    // Converts XY point from Spherical Mercator EPSG:900913 to lat/lon in WGS84 Datum
    // Fuente: http://www.maptiler.org/google-maps-coordinates-tile-bounds-projection/
    var originShift = 2.0 * PI * 6378137.0 / 2.0;

    var lon = (x / originShift) * 180.0;
    var lat = (y / originShift) * 180.0;

    lat = 180.0 / PI * (2.0 * Atan( Exp( lat * PI / 180.0)) - PI / 2.0);
    return [lat, lon]; 
    
  }


var center = Centroid(Geometry($feature));
var latlon = MetersToLatLon(center.x, center.y);

// Return Google Map
return 'https://www.google.com/maps/@' + latlon[0] + ',' + latlon[1] + ',83m/data=!3m1!1e3!5m1!1e4?entry=ttu';
